#include <iostream>
#include <string>

class Employee {
public:
    std::string name;
    double salary;

    double yearlyPay() const {
        return salary * 12;
    }

    void promote(double raise) {
        salary += raise;
    }
};

int main() {
    Employee worker;
    worker.name = "Anna";
    worker.salary = 1500.0;

    worker.promote(300.0);
    std::cout << worker.name << " earns "
              << worker.yearlyPay() << " per year" << std::endl;
    return 0;
}

#include <iostream>
#include <string>

class Account {
private:                 // inaccessible from outside
    std::string owner = "Bob";
    int balance = 0;

public:
    void deposit(int amount) {
        if (amount > 0) {
            balance += amount;   // invariant: no negative deposits
        }
    }

    int getBalance() const {
        return balance;
    }

    void setOwner(const std::string& name) {
        owner = name;
    }

    std::string getOwner() const {
        return owner;
    }
};

int main() {
    Account acc;
    std::cout << acc.getOwner() << " has " << acc.getBalance() << std::endl;

    acc.setOwner("Alice");
    acc.deposit(100);
    acc.deposit(-5);                     // rejected by the check
    std::cout << "now: " << acc.getBalance() << std::endl;

    // std::cout << acc.balance;         // error: balance is private
    return 0;
}

#include <iostream>

class Point {
private:
    int x;
    int y;

public:
    // Default constructor: member list x(0), y(0)
    Point() : x(0), y(0) {
        std::cout << "default ctor" << std::endl;
    }

    // Parameterized: initializes fields directly from arguments
    Point(int px, int py) : x(px), y(py) {}

    ~Point() {
        std::cout << "destroy " << x << ',' << y << std::endl;
    }

    void show() const {
        std::cout << '(' << x << ',' << y << ')' << std::endl;
    }
};

int main() {
    Point a;          // default ctor
    Point b(3, 4);    // parameterized ctor

    a.show();
    b.show();
    return 0;         // destructors run in reverse order: b, then a
}

#include <iostream>
#include <string>

class Employee {
protected:              // visible to derived classes too
    std::string name;
    double salary;

public:
    Employee(const std::string& n, double s) : name(n), salary(s) {}

    void show() const {
        std::cout << name << ": " << salary << std::endl;
    }
};

class Manager : public Employee {
private:
    int reports;

public:
    // Base constructor called in the init list
    Manager(const std::string& n, double s, int r)
        : Employee(n, s), reports(r) {}

    void teamInfo() const {
        std::cout << name << " manages " << reports << std::endl;
    }
};

int main() {
    Manager boss("Anna", 2000.0, 5);
    boss.show();        // inherited method
    boss.teamInfo();    // own method
    return 0;
}

#include <iostream>
#include <vector>

class Shape {
public:
    virtual double area() const {
        return 0.0;
    }

    virtual ~Shape() {}
};

class Circle : public Shape {
private:
    double r;

public:
    explicit Circle(double radius) : r(radius) {}

    double area() const override {
        return 3.14 * r * r;
    }
};

class Rect : public Shape {
private:
    double w;
    double h;

public:
    Rect(double width, double height) : w(width), h(height) {}

    double area() const override {
        return w * h;
    }
};

int main() {
    Circle c(1.0);
    Rect r(2.0, 3.0);

    std::vector<const Shape*> shapes = {&c, &r};
    double total = 0;
    for (const Shape* s : shapes) {
        total += s->area();      // resolved at runtime
    }
    std::cout << "total: " << total << std::endl;
    std::cout << c.area() << ' ' << r.area() << std::endl;
    return 0;
}

#include <iostream>
#include <string>

class Command {           // contract: what a command can do
public:
    virtual std::string name() const = 0;
    virtual void execute() const = 0;

    virtual ~Command() {}
};

class PrintCommand : public Command {
public:
    std::string name() const override {
        return "print";
    }

    void execute() const override {
        std::cout << "printing doc" << std::endl;
    }
};

class SaveCommand : public Command {
public:
    std::string name() const override {
        return "save";
    }

    void execute() const override {
        std::cout << "saving doc" << std::endl;
    }
};

int main() {
    PrintCommand printCmd;
    SaveCommand saveCmd;
    // Command c;         // error: Command is abstract

    const Command* cmds[] = {&printCmd, &saveCmd};
    for (const Command* c : cmds) {
        std::cout << c->name() << ": ";
        c->execute();
    }
    return 0;
}

#include <iostream>

class Vector2 {
public:
    double x;
    double y;

    Vector2(double px = 0.0, double py = 0.0) : x(px), y(py) {}

    // Operator as a member function
    Vector2 operator+(const Vector2& other) const {
        return Vector2(x + other.x, y + other.y);
    }

    bool operator==(const Vector2& other) const {
        return x == other.x && y == other.y;
    }
};

int main() {
    Vector2 a(1, 2);
    Vector2 b(3, 4);

    Vector2 c = a + b;
    std::cout << c.x << ' ' << c.y << std::endl;

    std::cout << (a == Vector2(1, 2)) << ' ' << (a == b) << std::endl;
    return 0;
}

#include <iostream>

class Vector2 {
public:
    double x;
    double y;

    Vector2(double px = 0.0, double py = 0.0) : x(px), y(py) {}
};

// Free function: the left operand is the stream, not this object
std::ostream& operator<<(std::ostream& out, const Vector2& v) {
    out << v.x << ',' << v.y;
    return out;
}

int main() {
    Vector2 a(2, 5);
    std::cout << a << std::endl;
    std::cout << Vector2(0, 0) << std::endl;
    return 0;
}

#include <iostream>
#include <string>

class Counter {
private:
    std::string name;
    int value;
    static int totalCreated;   // one copy for ALL objects

public:
    Counter(const std::string& n) : name(n), value(0) {
        ++totalCreated;
    }

    void increment() {
        ++value;               // same as this->value
    }

    void show() const {
        std::cout << name << '=' << value << std::endl;
    }

    static int total() {       // no `this`: class-level query
        return totalCreated;
    }
};

int Counter::totalCreated = 0;   // static member definition

int main() {
    Counter a("a");
    Counter b("b");

    a.increment();
    a.increment();
    b.increment();

    a.show();
    b.show();
    std::cout << "created: " << Counter::total() << std::endl;
    return 0;
}
